CREATE OR REPLACE FUNCTION public.craft_equipment_recipe(p_recipe_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid(); v_recipe jsonb; v_reward jsonb; v_bonus jsonb;
  v_money_cost double precision; v_progress jsonb; v_req jsonb; v_idx integer;
  v_key text; v_target numeric; v_have numeric; v_required_equipment text;
  v_new_money double precision; v_total_rolls bigint;
  v_potion record; v_remaining integer; v_take integer;
  v_best_100k double precision; v_best_1m double precision;
  v_auto_equip boolean;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select coalesce(cp.progress->'_equipment_recipe',r.recipe) into v_recipe
  from public.game_recipes r
  left join public.crafting_progress cp
    on cp.recipe_id=r.id and cp.player_id=v_uid
  where r.id=p_recipe_id;
  if v_recipe is null then raise exception 'recipe_not_found'; end if;
  v_reward:=v_recipe->'reward';
  if v_reward is null or v_reward->>'type'='consumable' then raise exception 'recipe_not_found'; end if;
  v_bonus:=coalesce(v_reward->'bonus','{}'::jsonb);
  v_money_cost:=coalesce((v_recipe->>'moneyCost')::double precision,0);
  v_auto_equip:=not (
    v_reward->>'category'='pickaxe'
    and coalesce((v_recipe->>'horizontal')::boolean,false)
    and coalesce(v_recipe->>'craftingTab','pickaxe')<>'toys'
  );

  select money,total_rolls,best_rare_natural_weight_100k,best_rare_natural_weight_1m
  into v_new_money,v_total_rolls,v_best_100k,v_best_1m
  from public.players where id=v_uid for update;
  if not found then raise exception 'player_not_found'; end if;

  select progress into v_progress from public.crafting_progress
  where player_id=v_uid and recipe_id=p_recipe_id;
  v_progress:=coalesce(v_progress,'{}'::jsonb);

  for v_req,v_idx in
    select value,(ordinality-1)::integer
    from jsonb_array_elements(coalesce(v_recipe->'requirements','[]'::jsonb)) with ordinality
  loop
    if v_req->>'type'='equipment' then
      if not exists(
        select 1 from public.player_equipment
        where player_id=v_uid
          and (
            equipment_id=v_req->>'equipmentId'
            or (
              p_recipe_id='plastic-shopping-bag'
              and v_req->>'equipmentId'='omnidimensional-vault'
              and equipment_id='dimensional-vault'
            )
          )
      ) then raise exception 'requirements_not_met'; end if;
    elsif v_req->>'type'='equipment-history' then
      if coalesce((public.equipment_batch_progress(v_uid)->>(v_req->>'metric'))::numeric,0)<(v_req->>'amount')::numeric
      then raise exception 'requirements_not_met'; end if;
    elsif v_req->>'type'='special-discoveries' then
      if public.equipment_special_discoveries(v_uid,v_req->>'classification')<(v_req->>'amount')::integer
      then raise exception 'requirements_not_met'; end if;
    elsif v_req->>'type'='potion-tier' then
      v_remaining:=(v_req->>'amount')::integer;
      for v_potion in
        select pc.consumable_id,pc.quantity
        from public.player_consumables pc
        join public.game_consumables c on c.id=pc.consumable_id
        where pc.player_id=v_uid
          and c.tier=(v_req->>'tier')::integer
          and c.duration_seconds>1
          and c.family in ('luck','rollSpeed','weightLuck','weightMultiplier')
        order by pc.consumable_id for update of pc
      loop
        v_take:=least(v_remaining,v_potion.quantity);
        update public.player_consumables
        set quantity=quantity-v_take,updated_at=now()
        where player_id=v_uid and consumable_id=v_potion.consumable_id;
        v_remaining:=v_remaining-v_take;
        exit when v_remaining=0;
      end loop;
      if v_remaining>0 then raise exception 'requirements_not_met'; end if;
    elsif v_req->>'type'='consumable' then
      update public.player_consumables
      set quantity=quantity-(v_req->>'amount')::integer,updated_at=now()
      where player_id=v_uid
        and consumable_id=v_req->>'consumableId'
        and quantity>=(v_req->>'amount')::integer;
      if not found then raise exception 'requirements_not_met'; end if;
    elsif v_req->>'type'='lifetime-rolls' then
      if coalesce(v_total_rolls,0)<coalesce((v_req->>'rolls')::bigint,0)
      then raise exception 'requirements_not_met'; end if;
    elsif v_req->>'type'='roll-history-condition' then
      v_have:=case when coalesce((v_req->>'minimumRarity')::numeric,0)>=1000000
        then coalesce(v_best_1m,0) else coalesce(v_best_100k,0) end;
      if v_have<coalesce((v_req->>'minimumWeightMultiplier')::numeric,0)
      then raise exception 'requirements_not_met'; end if;
    elsif v_req->>'type'='rarity-points' then
      v_key:=coalesce(v_req->>'id','rarity-points-'||v_idx::text);
      if coalesce((v_progress->v_key->>'points')::numeric,0)<coalesce((v_req->>'points')::numeric,0)
        or jsonb_array_length(coalesce(v_progress->v_key->'gemTypes','[]'::jsonb))<coalesce((v_req->>'minimumUniqueGemTypes')::integer,0)
      then raise exception 'requirements_not_met'; end if;
    elsif v_req->>'type'='gem-range' then
      v_key:=coalesce(v_req->>'id','gem-range-'||v_idx::text);
      if exists(
        select 1
        from jsonb_array_elements_text(coalesce(v_req->'gems','[]'::jsonb)) gem
        where coalesce((v_progress->v_key->>gem.value)::numeric,0)<coalesce((v_req->>'amountEach')::numeric,1)
      ) then raise exception 'requirements_not_met'; end if;
    else
      v_key:=coalesce(v_req->>'id',case
        when v_req->>'type'='gem-count' then v_req->>'gem'
        when v_req->>'type'='consumable' then coalesce(v_req->>'consumableId','consumable-'||v_idx::text)
        else (v_req->>'type')||'-'||v_idx::text end);
      v_target:=case v_req->>'type'
        when 'gem-total-weight' then coalesce((v_req->>'totalWeight')::numeric,0)
        when 'specimen-total-weight' then coalesce((v_req->>'totalWeight')::numeric,0)
        when 'specimen-value-total' then coalesce((v_req->>'totalValue')::numeric,0)
        else coalesce((v_req->>'amount')::numeric,1) end;
      v_have:=coalesce((v_progress->>v_key)::numeric,0);
      if v_have<v_target then raise exception 'requirements_not_met'; end if;
    end if;
  end loop;

  if v_new_money<v_money_cost then raise exception 'not_enough_money'; end if;
  select r->>'equipmentId' into v_required_equipment
  from jsonb_array_elements(coalesce(v_recipe->'requirements','[]'::jsonb)) r
  where r->>'type'='equipment' limit 1;

  -- Linear secondaries consume their preceding tier. Horizontal builds and
  -- ownership gates do not.
  if v_required_equipment is not null
     and not coalesce((v_recipe->>'includedSpecimens')::boolean,false)
     and not coalesce((v_recipe->>'horizontal')::boolean,false)
     and not exists(
       select 1 from jsonb_array_elements(v_recipe->'requirements') q
       where q->>'type'='equipment' and q->>'consume'='false'
     ) then
    delete from public.player_equipment
    where player_id=v_uid and equipment_id=v_required_equipment;
  end if;

  if v_auto_equip then
    update public.player_equipment
    set equipped=false
    where player_id=v_uid and category=v_reward->>'category' and equipped;
  end if;

  insert into public.player_equipment(
    player_id,equipment_id,category,tier,name,luck_bonus,roll_speed_bonus,
    weight_luck_bonus,weight_multiplier_bonus,equipped
  ) values(
    v_uid,v_reward->>'id',v_reward->>'category',coalesce((v_reward->>'tier')::integer,1),
    v_reward->>'name',coalesce((v_bonus->>'luck')::double precision,0),
    coalesce((v_bonus->>'rollSpeed')::double precision,0),
    coalesce((v_bonus->>'weightLuck')::double precision,0),
    coalesce((v_bonus->>'weightMultiplier')::double precision,0),v_auto_equip
  ) on conflict(player_id,equipment_id) do update set
    category=excluded.category,tier=excluded.tier,name=excluded.name,
    luck_bonus=excluded.luck_bonus,roll_speed_bonus=excluded.roll_speed_bonus,
    weight_luck_bonus=excluded.weight_luck_bonus,
    weight_multiplier_bonus=excluded.weight_multiplier_bonus,
    equipped=excluded.equipped;

  update public.players set money=money-v_money_cost
  where id=v_uid returning money into v_new_money;
  delete from public.crafting_progress
  where player_id=v_uid and recipe_id=p_recipe_id;
  update public.player_crafting set
    active_auto_craft=case when active_auto_craft=p_recipe_id then null else active_auto_craft end,
    updated_at=now()
  where player_id=v_uid;
  return jsonb_build_object(
    'money',v_new_money,
    'equipmentId',v_reward->>'id',
    'equipped',v_auto_equip
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.deposit_equipment_material(p_player_id uuid, p_recipe_id text, p_specimen jsonb DEFAULT NULL::jsonb, p_requirement_index integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_req jsonb;
  v_key text;
  v_remaining integer;
  v_count integer;
  v_ids bigint[];
  v_recipe jsonb;
  v_progress jsonb;
  v_plan jsonb;
  v_gem public.inventory_gems%rowtype;
  v_preserved boolean := false;
  v_chance numeric := 0;
  v_manual boolean := p_specimen is null;
begin
  perform 1 from public.players where id = p_player_id for update;
  if not found then raise exception 'player_not_found'; end if;

  select recipe into v_recipe from public.game_recipes where id = p_recipe_id;
  if v_recipe is null then raise exception 'recipe_not_found'; end if;

  if p_recipe_id = 'impossible-pickaxe' then
    if v_manual then
      return jsonb_build_object('deposited', false, 'reason', 'use_impossible_workspace');
    end if;
    return impossible_private.deposit_specimen(p_player_id, p_specimen, true);
  end if;

  insert into public.crafting_progress(player_id, recipe_id, progress)
  values (p_player_id, p_recipe_id, '{}')
  on conflict do nothing;

  select progress into v_progress
  from public.crafting_progress
  where player_id = p_player_id and recipe_id = p_recipe_id
  for update;

  v_recipe := coalesce(v_progress->'_equipment_recipe', v_recipe);

  -- Consumed recipes intentionally deposit every currently eligible specimen
  -- in one statement. This now accepts specimen-condition requirements and
  -- mirrors every predicate supported by plan_equipment_material.
  if v_manual and v_recipe->>'consumeMaterials' = 'true' then
    v_req := v_recipe->'requirements'->p_requirement_index;
    if p_requirement_index is null
      or p_requirement_index < 0
      or v_req->>'type' not in ('gem-count', 'specimen-condition') then
      raise exception 'invalid_bulk_requirement';
    end if;

    v_key := coalesce(v_req->>'id', v_req->>'gem');
    if v_key is null then raise exception 'invalid_bulk_requirement'; end if;

    v_remaining := greatest(
      0,
      (v_req->>'amount')::integer - coalesce((v_progress->>v_key)::integer, 0)
    );

    select coalesce(array_agg(id), '{}'::bigint[])
    into v_ids
    from (
      select id
      from public.inventory_gems
      where player_id = p_player_id
        and not locked
        and not coalesce(museum_locked, false)
        and rarity >= coalesce((v_req->>'minimumRarity')::numeric, 0)
        and rarity <= coalesce((v_req->>'maximumRarity')::numeric, 1e100)
        and (not (v_req ? 'gem') or gem_name = v_req->>'gem')
        and (
          not (v_req ? 'minimumWeightMultiplier')
          or final_weight / nullif(base_weight, 0)
            >= (v_req->>'minimumWeightMultiplier')::numeric
        )
        and (
          not (v_req ? 'maximumWeightMultiplier')
          or final_weight / nullif(base_weight, 0)
            <= (v_req->>'maximumWeightMultiplier')::numeric
        )
        and (
          not (v_req ? 'minimumFinalWeight')
          or final_weight >= (v_req->>'minimumFinalWeight')::numeric
        )
        and (
          not (v_req ? 'minimumValue')
          or value >= (v_req->>'minimumValue')::numeric
        )
      order by
        case when v_req ? 'minimumValue' then value end,
        case when v_req ? 'minimumFinalWeight' then final_weight end,
        final_weight,
        id
      limit v_remaining
      for update
    ) eligible;

    v_count := cardinality(v_ids);
    if v_count = 0 then
      return jsonb_build_object('deposited', false, 'progress', v_progress);
    end if;

    delete from public.inventory_gems
    where player_id = p_player_id and id = any(v_ids);

    v_progress := jsonb_set(
      v_progress,
      array[v_key],
      to_jsonb(coalesce((v_progress->>v_key)::integer, 0) + v_count)
    );
    update public.crafting_progress
    set progress = v_progress, updated_at = now()
    where player_id = p_player_id and recipe_id = p_recipe_id;

    return jsonb_build_object(
      'deposited', true,
      'depositedCount', v_count,
      'progress', v_progress,
      'preserved', false
    );
  end if;

  if v_manual then
    if p_requirement_index is null then raise exception 'requirement_required'; end if;
    for v_gem in
      select *
      from public.inventory_gems
      where player_id = p_player_id
        and not coalesce(locked, false)
        and (not coalesce((v_recipe->>'includedSpecimens')::boolean, false) or base_weight > 0)
        and rarity >= coalesce((v_recipe->'requirements'->p_requirement_index->>'minimumRarity')::numeric, 0)
        and rarity <= coalesce((v_recipe->'requirements'->p_requirement_index->>'maximumRarity')::numeric, 1e100)
        and (not (v_recipe->'requirements'->p_requirement_index ? 'gem') or gem_name = v_recipe->'requirements'->p_requirement_index->>'gem')
        and (not (v_recipe->'requirements'->p_requirement_index ? 'minimumWeightMultiplier') or final_weight / nullif(base_weight, 0) >= (v_recipe->'requirements'->p_requirement_index->>'minimumWeightMultiplier')::numeric)
      order by final_weight, id
      for update
    loop
      v_plan := public.plan_equipment_material(v_recipe, v_progress, to_jsonb(v_gem), p_requirement_index);
      if v_plan is not null then exit; end if;
    end loop;
  else
    v_plan := public.plan_equipment_material(v_recipe, v_progress, p_specimen, p_requirement_index);
  end if;

  if v_plan is null then
    return jsonb_build_object('deposited', false, 'progress', v_progress);
  end if;

  if (v_plan->>'conservationEligible')::boolean then
    select coalesce(max(case equipment_id when 'plastic-shopping-bag' then 0.125 else 0 end), 0)
    into v_chance
    from public.player_equipment
    where player_id = p_player_id and equipped and category = 'bag';
    v_preserved := random() < v_chance;
  end if;

  update public.crafting_progress
  set progress = v_plan->'progress', updated_at = now()
  where player_id = p_player_id and recipe_id = p_recipe_id;

  if v_manual and not v_preserved then
    delete from public.inventory_gems where id = v_gem.id and player_id = p_player_id;
  end if;

  return v_plan || jsonb_build_object(
    'deposited', true,
    'preserved', v_preserved,
    'consumedSpecimen', case
      when v_manual and not v_preserved then jsonb_build_object(
        'id', v_gem.id,
        'gemName', v_gem.gem_name,
        'weight', v_gem.final_weight,
        'value', v_gem.value
      )
      else null
    end
  );
end
$function$
